'use strict';
// EVENTORIA: автономний сайт-прототип. Дані зберігаються ТІЛЬКИ у цьому браузері.
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const CATS = ['Весілля','Корпоративи','Дитячі свята'];
const CATICONS = {'Весілля':'✦','Корпоративи':'◈','Дитячі свята':'✦'};
const FALLBACKS = {'Весілля':'assets/wedding.svg','Корпоративи':'assets/corporate.svg','Дитячі свята':'assets/kids.svg','other':'assets/wedding.svg'};
const read = (key, fallback) => {try {let x=localStorage.getItem(key);return x===null?fallback:JSON.parse(x)}catch{return fallback}};
const write = (key,value) => {try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('Не вдалося зберегти дані. Перевірте пам’ять браузера.')}};
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = s => {let x=String(s||'').trim();return /^(https?:\/\/|assets\/)/i.test(x) ? x : '';};
const money = n => Number(n||0).toLocaleString('uk-UA')+' ₴';
const img = (url, alt='', category='Весілля', attrs='') => {
  const fallback=FALLBACKS[category]||FALLBACKS.other;
  const source=safeUrl(url)||fallback;
  const src=source.startsWith('assets/photos/') ? source+(source.includes('?')?'&':'?')+'v=6' : source;
  const eager=/hero-image/.test(attrs);
  return `<img loading="${eager?'eager':'lazy'}" decoding="async" src="${esc(src)}" alt="${esc(alt)}" onerror="this.onerror=null;this.src='${fallback}'" ${attrs}>`;
};
const fromSeed = key => JSON.parse(JSON.stringify(window[key]));
// Новий окремий набір даних: наявні пости/контакти старої версії, якщо вони були, збережені.
let services = read('ev3_services',fromSeed('SEED_SERVICES'));
let legacyPosts = read('ev_posts',null);
let posts = read('ev3_posts',Array.isArray(legacyPosts)?[...legacyPosts,...fromSeed('SEED_POSTS')]:fromSeed('SEED_POSTS'));
let portfolioItems = read('ev3_portfolio',read('ev_portfolio',fromSeed('SEED_PORTFOLIO')));
let manager = read('ev3_manager',read('ev_manager',fromSeed('SEED_MANAGER')));
let settings = read('ev3_settings',fromSeed('SEED_SETTINGS'));
// Одноразово застосувати опубліковану резервну копію до старих браузерних даних.
// Кошик, вподобання, повідомлення і заявки не змінюються.
try {
  if(localStorage.getItem('ev3_published_backup_20261113') !== 'yes') {
    services=fromSeed('SEED_SERVICES');
    posts=fromSeed('SEED_POSTS');
    portfolioItems=fromSeed('SEED_PORTFOLIO');
    manager=fromSeed('SEED_MANAGER');
    settings=fromSeed('SEED_SETTINGS');
    localStorage.setItem('ev3_published_backup_20261113','yes');
    [['ev3_services',services],['ev3_posts',posts],['ev3_portfolio',portfolioItems],
     ['ev3_manager',manager],['ev3_settings',settings]].forEach(([k,v])=>write(k,v));
  }
} catch(e) { /* браузер може забороняти localStorage */ }

let orders = read('ev3_orders',read('ev_orders',[]));
let messages = read('ev3_messages',read('ev_messages',[]));
let cart = read('ev3_cart',[]);
let favorites = read('ev3_favorites',[]);
// Міграція старих unsplash-посилань у надійні локальні фото, без втрати іншого редагування.
function isOldStockImage(url){return !url || /images\.unsplash\.com\//i.test(String(url));}
function photosFor(category){return window.EVENTORIA_LOCAL_PHOTOS[category] || window.EVENTORIA_LOCAL_PHOTOS['Весілля'];}
function migrateMedia(){
  const counts={'Весілля':0,'Корпоративи':0,'Дитячі свята':0};
  services=services.map(s=>{
    const pics=photosFor(s.category), idx=(counts[s.category]||0); counts[s.category]=idx+1;
    const cover=isOldStockImage(s.image)?pics[idx%pics.length]:s.image;
    const list=Array.isArray(s.gallery)?s.gallery:[];
    const gallery=Array.from({length:Math.max(4,list.length)},(_,i)=>isOldStockImage(list[i])?pics[(idx+i)%pics.length]:list[i]);
    return {...s,image:cover,gallery};
  });
  // Не змінюємо фотографії статей, які обрав автор, включно з URL.
  portfolioItems=portfolioItems.map((x,i)=>({...x,image:isOldStockImage(x.image)?photosFor(x.category)[i%photosFor(x.category).length]:x.image}));
  if(isOldStockImage(manager.photo))manager={...manager,photo:'assets/photos/manager.jpg'};
if((manager.photo||'').endsWith('manager.jpg.jpg')) manager={...manager,photo:'assets/photos/manager.jpg'};
}
migrateMedia();
// Keep all the user's edited text, prices and service data; only refresh old built-in demo photos.
function usePhotoForService(){
 const map=window.EVENTORIA_SERVICE_MEDIA||{};
 const demo=x=>!x||/^(assets\/photos\/|https?:\/\/images\.unsplash\.com\/)/i.test(String(x));
 services=services.map(s=>{
  const photo=map[String(s.id)]; if(!photo)return s;
  const oldGallery=Array.isArray(s.gallery)?s.gallery:[];
  const customGallery=oldGallery.some(x=>!demo(x));
  return {...s,image:demo(s.image)?photo.image:s.image,gallery:customGallery?oldGallery:[...photo.gallery]};
 });
}
usePhotoForService();
// Photo editor has higher priority than demo images, including images cached by older versions.
// Each service gets its own gallery. Do not rotate unrelated category images into it.
const photoConfig=window.EVENTORIA_PHOTO_CONFIG||{services:{},portfolio:{}};
services=services.map(s=>{const custom=(photoConfig.services||{})[String(s.id)];return custom?{...s,image:custom.image,gallery:[...custom.gallery]}:s;});
portfolioItems=portfolioItems.map(p=>{const custom=(photoConfig.portfolio||{})[String(p.id)];return custom?{...p,image:custom.image,gallery:[...custom.gallery]}:p;});
// Old starter blog references to deleted duplicated files are redirected to existing images.
const validStarterMedia=new Set(['wedding_01.webp','wedding_02.webp','wedding_03.webp','wedding_04.webp','corporate_01.webp','corporate_02.webp','corporate_03.webp','kids_01.webp','kids_02.webp','kids_03.webp','kids_fairytale.webp','kids_graduation.webp','kids_science.webp','kids_sleepover.webp']);
posts=posts.map((post,i)=>{
  const match=String(post.image||'').match(/^assets\/photos\/((?:wedding|corporate|kids)_\d{2}\.webp)$/);
  if(match&&!validStarterMedia.has(match[1])){
    const replacements=['assets/photos/wedding_02.webp','assets/photos/wedding_03.webp','assets/photos/corporate_02.webp','assets/photos/kids_01.webp'];
    return {...post,image:replacements[i%replacements.length]};
  }
  return post;
});

let filteredFavs = false;
let selectedGallery = 0;
const page = (location.pathname.split('/').pop()||'index.html').replace('.html','');
function save(){write('ev3_services',services);write('ev3_posts',posts);write('ev3_portfolio',portfolioItems);write('ev3_manager',manager);write('ev3_settings',settings);write('ev3_orders',orders);write('ev3_messages',messages);write('ev3_cart',cart);write('ev3_favorites',favorites)}
function notifyCounts(){let c=$('#cartCount'),f=$('#favCount');if(c)c.textContent=cart.length;if(f)f.textContent=favorites.length}
function toast(s){let el=$('#toast');if(!el){el=document.createElement('div');el.id='toast';el.className='toast';document.body.appendChild(el)}el.textContent=s;el.classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>el.classList.remove('show'),3400)}
const iconLink = (id, text) => `<button class="iconbtn" onclick="${id}" aria-label="${esc(text)}" title="${esc(text)}">×</button>`;
